body:
I was able to work around this by hiding the implementation in a base class. However, that means all my custom controls have to inherit from this one so I can't extend other Control types. The bug still needs a fix.

```csharp
// this hides the buggy Godot method because C# will prefer the signature with the exact type
protected Color GetThemeColor(string name) => GetThemeColor(name, HasThemeColorOverride(name) ? null : ThemeName);
```

Here's an example of my current, best solution:

![Image](https://github.com/user-attachments/assets/c18a5c58-d3d6-4f42-9fc8-e39cb627695c)



<details><summary>ThemableControl.cs</summary>

```csharp
#pragma warning disable IDE1006

public abstract partial class ThemableControl : Control
{
    protected const string THEME_GROUP = "Theme Overrides";
    protected const string THEME_SUB_COLORS = "Colors";
    protected const string THEME_SUB_CONSTANTS = "Constants";
    protected const string THEME_SUB_FONTS = "Fonts";
    protected const string THEME_SUB_FONT_SIZES = "Font Sizes";
    protected const string THEME_SUB_ICONS = "Icons";
    protected const string THEME_SUB_STYLES = "Styles";

    /// <summary>
    /// Class name to search for during theme traversal. Example: nameof(MyClass)
    /// Consider calling EmitSignalThemeChanged() if you change this after init.
    /// </summary>
    protected StringName ThemeName { get; set; }

    private bool initializing = true; // don't skip the first ThemeChanged if overrides are set
    private bool skipThemeChangedEvent;

    public ThemableControl()
    {
        ThemeName = GetType().Name;
        ThemeChanged += OnThemeChanged;
    }

    /// <summary>
    /// This gets called when the ThemeChanged event pops. However, unlike the event, it
    /// doesn't pop if a single property is overridden with one of the OverrideSetter helpers.
    /// This is to cut down on theme traversal when setting one property at a time.
    /// QueueRedraw() is called automatically when any theme property is changed.
    /// 
    /// Example:
    ///     _OnThemeChanged()
    ///     {
    ///         my_color = GetThemeColor(nameof(my_color))
    ///     }
    /// </summary>
    protected virtual void _ThemeChanged() { }

    protected Color GetThemeColor(string name) => GetThemeColor(name, HasThemeColorOverride(name) ? null : ThemeName);
    protected int GetThemeConstant(string name) => GetThemeConstant(name, HasThemeConstantOverride(name) ? null : ThemeName);
    protected Font GetThemeFont(string name) => GetThemeFont(name, HasThemeFontOverride(name) ? null : ThemeName);
    protected int GetThemeFontSize(string name) => GetThemeFontSize(name, HasThemeFontSizeOverride(name) ? null : ThemeName);
    protected Texture2D GetThemeIcon(string name) => GetThemeIcon(name, HasThemeIconOverride(name) ? null : ThemeName);
    protected StyleBox GetThemeStylebox(string name) => GetThemeStylebox(name, HasThemeStyleboxOverride(name) ? null : ThemeName);

    protected Color ThemeColorOverrideSetter(string themPropertyName, Color value)
    {
        skipThemeChangedEvent = true;
        if (HasThemeColorOverride(themPropertyName) && value == default) RemoveThemeColorOverride(themPropertyName);
        else AddThemeColorOverride(themPropertyName, value);
        return GetThemeColor(themPropertyName);
    }

    protected int ThemeConstantOverrideSetter(string themPropertyName, int value)
    {
        skipThemeChangedEvent = true;
        if (HasThemeConstantOverride(themPropertyName) && value == default) RemoveThemeConstantOverride(themPropertyName);
        else AddThemeConstantOverride(themPropertyName, value);
        return GetThemeConstant(themPropertyName);;
    }

    protected Font ThemeFontOverrideSetter(string themPropertyName, Font value)
    {
        skipThemeChangedEvent = true;
        if (HasThemeFontOverride(themPropertyName) && value is null) RemoveThemeFontOverride(themPropertyName);
        else AddThemeFontOverride(themPropertyName, value);
        return GetThemeFont(themPropertyName);;
    }

    protected int ThemeFontSizeOverrideSetter(string themPropertyName, int value)
    {
        skipThemeChangedEvent = true;
        if (HasThemeFontSizeOverride(themPropertyName) && value == default) RemoveThemeFontSizeOverride(themPropertyName);
        else AddThemeFontSizeOverride(themPropertyName, value);
        return GetThemeFontSize(themPropertyName);;
    }

    protected Texture2D ThemeIconOverrideSetter(string themPropertyName, Texture2D value)
    {
        skipThemeChangedEvent = true;
        if (HasThemeIconOverride(themPropertyName) && value is null) RemoveThemeIconOverride(themPropertyName);
        else AddThemeIconOverride(themPropertyName, value);
        return GetThemeIcon(themPropertyName);;
    }

    protected StyleBox ThemeStyleboxOverrideSetter(string themPropertyName, StyleBox value)
    {
        skipThemeChangedEvent = true;
        if (HasThemeStyleboxOverride(themPropertyName) && value is null) RemoveThemeStyleboxOverride(themPropertyName);
        else AddThemeStyleboxOverride(themPropertyName, value);
        return GetThemeStylebox(themPropertyName);;
    }

    private void OnThemeChanged()
    {
        if (initializing || !skipThemeChangedEvent) _ThemeChanged();
        else skipThemeChangedEvent = false;
        initializing = false;
        QueueRedraw();
    }
}
```
</details>



<details><summary>HypergamooseDisplay.cs (much less clutter)</summary>

```csharp
public partial class HypergamooseDisplay : ThemableControl
{
    private Color sheet_color;
    [Export][ExportGroup(THEME_GROUP)][ExportSubgroup(THEME_SUB_COLORS)]
    public Color SheetColor {
        get => sheet_color;
        set => sheet_color = ThemeColorOverrideSetter(nameof(sheet_color), value);
    }

    private Color line_color;
    [Export][ExportGroup(THEME_GROUP)][ExportSubgroup(THEME_SUB_COLORS)]
    public Color LineColor {
        get => line_color;
        set => line_color = ThemeColorOverrideSetter(nameof(line_color), value);
    }

    private Color select_color;
    [Export][ExportGroup(THEME_GROUP)][ExportSubgroup(THEME_SUB_COLORS)]
    public Color SelectColor {
        get => select_color;
        set => select_color = ThemeColorOverrideSetter(nameof(select_color), value);
    }

    private Color cursor_color;
    [Export][ExportGroup(THEME_GROUP)][ExportSubgroup(THEME_SUB_COLORS)]
    public Color CursorColor {
        get => cursor_color;
        set => cursor_color = ThemeColorOverrideSetter(nameof(cursor_color), value);
    }

    private Font font;
    [Export][ExportGroup(THEME_GROUP)][ExportSubgroup(THEME_SUB_FONTS)]
    public Font Font {
        get => font;
        set => font = ThemeFontOverrideSetter(nameof(font), value);
    }

    private int note_font_size; //  = 24
    [Export][ExportGroup(THEME_GROUP)][ExportSubgroup(THEME_SUB_FONT_SIZES)]
    public int NoteFontSize {
        get => note_font_size;
        set => note_font_size = ThemeFontSizeOverrideSetter(nameof(note_font_size), value);
    }

    private int title_font_size; //  = 32
    [Export][ExportGroup(THEME_GROUP)][ExportSubgroup(THEME_SUB_FONT_SIZES)]
    public int TitleFontSize {
        get => title_font_size;
        set => title_font_size = ThemeFontSizeOverrideSetter(nameof(title_font_size), value);
    }

    public HypergamooseDisplay()
    {
        ThemeName = "MusicDisplay";
    }

    protected override void _OnThemeChanged()
    {
        sheet_color = GetThemeColor(nameof(sheet_color));
        line_color = GetThemeColor(nameof(line_color));
        select_color = GetThemeColor(nameof(select_color));
        cursor_color = GetThemeColor(nameof(cursor_color));
        font = GetThemeFont(nameof(font));
        note_font_size = GetThemeFontSize(nameof(note_font_size));
        title_font_size = GetThemeFontSize(nameof(title_font_size));
    }
}
```
